files.content:
[hidden] { display: none !important; }

:root {
  --bg: #1e1e2f;
  --card: #2a2a40;
  --text: #f0f0f5;
  --accent: #ffb347;
  --accent-hover: #ffc46b;
  --accent-pressed: #e09a2e;
  --hunger: #ff6b6b;
  --happiness: #ffd93d;
  --energy: #6bcb77;
  --bar-bg: #3a3a55;
  --focus-ring: #ffffff;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  color: var(--text);
  padding: 16px;
}

.game-card {
  background: var(--card);
  border-radius: 24px;
  padding: 28px 24px;
  width: 100%;
  max-width: 420px;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 24px;
}

h1 {
  margin: 0;
  font-size: 1.8rem;
  text-align: center;
  letter-spacing: 1px;
  color: var(--accent);
}

.pet-stage {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.pet {
  width: 120px;
  height: 120px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.2s ease;
}

.pet-body {
  position: relative;
  width: 100px;
  height: 100px;
  background: var(--accent);
  border-radius: 16px;
  box-shadow:
    inset -8px -8px 0 rgba(0, 0, 0, 0.15),
    0 0 0 6px var(--card),
    0 0 0 10px var(--accent);
}

.pet-eye {
  position: absolute;
  width: 14px;
  height: 14px;
  background: var(--bg);
  border-radius: 50%;
  top: 30px;
}

.pet-eye.left { left: 22px; }
.pet-eye.right { right: 22px; }

.pet-mouth {
  position: absolute;
  width: 24px;
  height: 12px;
  border-bottom: 4px solid var(--bg);
  border-radius: 0 0 24px 24px;
  left: 50%;
  transform: translateX(-50%);
  bottom: 22px;
}

.mood {
  margin: 0;
  font-size: 1rem;
  text-align: center;
  min-height: 1.4em;
  color: var(--text);
  opacity: 0.9;
}

.stats {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.stat-label {
  display: flex;
  justify-content: space-between;
  font-size: 0.95rem;
  font-weight: 600;
}

.bar {
  height: 18px;
  background: var(--bar-bg);
  border-radius: 9px;
  overflow: hidden;
}

.fill {
  height: 100%;
  border-radius: 9px;
  transition: width 0.3s ease;
}

.fill.hunger { background: var(--hunger); }
.fill.happiness { background: var(--happiness); }
.fill.energy { background: var(--energy); }

.controls {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
}

.action-btn {
  flex: 1 1 100px;
  min-width: 90px;
  padding: 14px 12px;
  font-size: 1rem;
  font-weight: 700;
  font-family: inherit;
  color: var(--bg);
  background: var(--accent);
  border: 2px solid transparent;
  border-radius: 12px;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease, box-shadow 0.15s ease;
}

.action-btn:hover {
  background: var(--accent-hover);
}

.action-btn:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 3px;
}

.action-btn:active {
  background: var(--accent-pressed);
  transform: scale(0.97);
}

@media (max-width: 400px) {
  .game-card {
    padding: 20px 16px;
    gap: 20px;
  }
  h1 { font-size: 1.5rem; }
  .action-btn { flex: 1 1 100%; }
}

(function () {
  'use strict';

  var stats = { hunger: 70, happiness: 60, energy: 80 };
  var MAX = 100;
  var MIN = 0;

  var elements = {
    hunger: { fill: document.getElementById('hunger-fill'), bar: document.getElementById('hunger-bar'), value: document.getElementById('hunger-value') },
    happiness: { fill: document.getElementById('happiness-fill'), bar: document.getElementById('happiness-bar'), value: document.getElementById('happiness-value') },
    energy: { fill: document.getElementById('energy-fill'), bar: document.getElementById('energy-bar'), value: document.getElementById('energy-value') }
  };

  var moodEl = document.getElementById('mood');
  var petEl = document.getElementById('pet');

  function clamp(value) {
    return Math.max(MIN, Math.min(MAX, value));
  }

  function setStat(name, value) {
    stats[name] = clamp(value);
    var el = elements[name];
    el.fill.style.width = stats[name] + '%';
    el.bar.setAttribute('aria-valuenow', String(stats[name]));
    el.value.textContent = stats[name] + '%';
  }

  function getMood() {
    var avg = (stats.hunger + stats.happiness + stats.energy) / 3;
    if (avg >= 70) return 'Your pet is thriving! 😊';
    if (avg >= 40) return 'Your pet is feeling okay.';
    if (avg >= 20) return 'Your pet needs some attention.';
    return 'Your pet is not doing well...';
  }

  function renderMood() {
    moodEl.textContent = getMood();
  }

  function animatePet() {
    petEl.style.transform = 'scale(1.08)';
    setTimeout(function () {
      petEl.style.transform = 'scale(1)';
    }, 200);
  }

  function feed() {
    setStat('hunger', stats.hunger + 15);
    setStat('happiness', stats.happiness + 5);
    setStat('energy', stats.energy - 5);
    renderMood();
    animatePet();
  }

  function play() {
    setStat('happiness', stats.happiness + 15);
    setStat('energy', stats.energy - 10);
    setStat('hunger', stats.hunger - 5);
    renderMood();
    animatePet();
  }

  function sleep() {
    setStat('energy', stats.energy + 20);
    setStat('hunger', stats.hunger - 5);
    renderMood();
    animatePet();
  }

  document.getElementById('feed-btn').addEventListener('click', feed);
  document.getElementById('play-btn').addEventListener('click', play);
  document.getElementById('sleep-btn').addEventListener('click', sleep);

  renderMood();
})();
